function N292Action(a){if(!['notes','draw'].includes(de))return false;const handled=['notesTab','drawTab','calendar','noteprev','notenext','paint','erase','drawclear','drawretry','drawcheck','n292next','n292lifeprev','n292lifenext','n292again','n292back'];if(!handled.includes(a)&&!/^n292phase[0-7]$/.test(a))return false;dt.unlock();dt.sfx('click');
if(a==='notesTab'||a==='n292back'){ca(true);de='notes';N292.tab='phases';at?.setMode('notes');at?.setDay(vn*gt.cycle/8);On()}
else if(a==='drawTab'){if(de!=='draw')N293startMission();else return true}
else if(a==='calendar'){de='notes';N292.tab='life';On()}
else if(a==='noteprev'||a==='notenext'){vn=(vn+(a==='notenext'?1:7))%8;at?.setDay(vn*gt.cycle/8);On()}
else if(a==='n292lifeprev'||a==='n292lifenext'){N292.life=ki(N292.life+(a==='n292lifenext'?1:-1),0,4);On()}
else if(/^n292phase/.test(a))N292select(+a.slice(-1));
else if(a==='paint'||a==='erase'){pf=a==='paint';On()}
else if(a==='drawclear'||a==='drawretry'){N292reset();On()}
else if(a==='drawcheck'){Ps=N294score(bh,vn).score;N294.serial++;ar=true;N292.checked[vn]=true;if(Ps>=.85&&!ee.draw.includes(vn))ee.draw.push(vn);ee.notesArtChecked=N292.checked.map(Boolean);xi();dt.sfx('correct');On()}
else if(a==='n292next'&&Ps!==null){if(vn<7)N292select(vn+1);else if(N292.checked.every(Boolean)){N292.done=true;dt.sfx('victory');Nt('n292complete')}else{N292select(N292.checked.indexOf(false));N294notice(N292t('missing'))}}
else if(a==='n292again'){ca(true);N293startMission()}
return true}
