  pen.hidden=false;pen.style.left=x+'px';pen.style.top=y+'px';pen.style.setProperty('--tilt',N293motion()?ki(22+dx*1.5-dy*.25,-25,55)+'deg':'0deg');pen.classList.toggle('is-down',down);tip={x,y};
