function N294target(phase){if(N294targets.has(phase))return N294targets.get(phase);const target=new Uint8Array(10000),valid=new Uint8Array(10000),weight=new Float32Array(10000);let area=0,lit=0;
 for(let y=0;y<100;y++)for(let x=0;x<100;x++){const i=y*100+x,nx=(x-49.5)/49,ny=(y-49.5)/49;if(nx*nx+ny*ny>1)continue;valid[i]=1;area++;target[i]=gt.lit(nx,ny,phase*gt.cycle/8)?1:0;lit+=target[i]}
 for(let y=0;y<100;y++)for(let x=0;x<100;x++){const i=y*100+x;if(!valid[i])continue;let distance=2;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const xx=x+dx,yy=y+dy;if(xx<0||xx>=100||yy<0||yy>=100)continue;const j=yy*100+xx;if(valid[j]&&target[j]!==target[i])distance=Math.min(distance,Math.hypot(dx,dy))}weight[i]=distance/2}
 const data={target,valid,weight,area,lit};N294targets.set(phase,data);return data}
function N294score(mask,phase){const {target,valid,weight,area,lit}=N294target(phase);let tp=0,tn=0,fp=0,fn=0,painted=0;for(let i=0;i<10000;i++){if(!valid[i])continue;const actual=!!mask[i];painted+=actual?1:0;if(actual&&target[i])tp++;else if(!actual&&!target[i])tn++;else if(actual)fp+=weight[i];else fn+=weight[i]}
 let similarity;if(lit===0)similarity=1-painted/area;else if(lit===area)similarity=painted/area;else{const dice=tp?2*tp/(2*tp+fp+fn):0,balanced=.5*(tp/(tp+fn||1)+tn/(tn+fp||1));similarity=Math.sqrt(dice*balanced)}return {score:ki(similarity,0,1),percent:Math.round(ki(similarity,0,1)*100),area,painted,lit,tp,tn,fp,fn}}

