const N294L={en:{control:'Mission Control',match:'MOON MATCH!',accuracy:'Drawing Accuracy',approx:'Approx. drawing similarity — not a scientific measurement.',instructions:'Paint the lit part of your Moon. Check when you’re ready to compare!',tools:'Art tools',brush:'Brush',eraser:'Eraser',clear:'Clear',size:'Brush size',sizes:['Fine','Medium','Broad'],check:'Check Drawing',retry:'Retry',your:'Your Moon Art',reference:'Correct Moon',progress:'Mission progress',complete:'checked',feedback:['Good start! Explore a different lit shape.','Keep exploring! Compare both shapes.','Lovely effort! Fine-tune the lit edge.','Great Moon Art!'],entry:'Open Moon Art',entryNote:'Moon Art works on this portrait screen.',small:'For Moon Art, use a larger portrait screen or a supported landscape screen.',help:['Enter Moon Art at New Moon. Pick a named mission or check and move through all eight.','Paint with a mouse, touch or stylus. Choose Brush, Eraser and brush size; Clear starts this phase again.','Check reveals the correct Moon and an approximate drawing similarity score. Both missing light and extra light count.','Retry as often as you like. Next Moon is available after every check, whatever the score.']},bm:{control:'Kawalan Misi',match:'PADANAN BULAN!',accuracy:'Ketepatan Lukisan',approx:'Anggaran kesamaan lukisan — bukan ukuran saintifik.',instructions:'Warnakan bahagian terang Bulan. Semak apabila bersedia untuk membandingkan!',tools:'Alat melukis',brush:'Berus',eraser:'Pemadam',clear:'Padam',size:'Saiz berus',sizes:['Halus','Sederhana','Lebar'],check:'Semak Lukisan',retry:'Cuba Lagi',your:'Seni Bulan Anda',reference:'Bulan Rujukan',progress:'Kemajuan misi',complete:'disemak',feedback:['Permulaan yang baik! Cuba bentuk terang yang lain.','Teruskan meneroka! Bandingkan kedua-dua bentuk.','Usaha yang bagus! Perhalus sempadan terang.','Hebatnya seni Bulan anda!'],entry:'Buka Seni Bulan',entryNote:'Seni Bulan boleh digunakan pada skrin menegak ini.',small:'Untuk Seni Bulan, gunakan skrin menegak yang lebih besar atau skrin melintang yang sesuai.',help:['Mula dengan Anak Bulan. Pilih misi mengikut nama atau semak dan teruskan semua lapan fasa.','Lukis dengan tetikus, sentuhan atau stilus. Pilih Berus, Pemadam dan saiz berus; Padam untuk mula semula.', 'Semak untuk melihat rujukan dan anggaran kesamaan lukisan. Bahagian terang yang kurang dan berlebihan diambil kira.','Cuba lagi seberapa kerap yang anda mahu. Bulan Seterusnya tersedia selepas setiap semakan, tanpa mengira peratus.']},zh:{control:'任务控制台',match:'月相匹配！',accuracy:'画作准确度',approx:'画作相似度的估计值，并非科学测量。',instructions:'涂出月亮明亮的部分。准备好后，检查并比较画作！',tools:'绘画工具',brush:'画笔',eraser:'橡皮擦',clear:'清除',size:'画笔大小',sizes:['细','中','粗'],check:'检查画作',retry:'再试一次',your:'你的月亮画作',reference:'正确月相',progress:'任务进度',complete:'已检查',feedback:['好的开始！试试不同的明亮形状。','继续探索！比较两个形状。','画得不错！再调整明暗边界。','月亮画得真棒！'],entry:'进入月亮画室',entryNote:'月亮画室支持这个竖屏。',small:'请使用较大的竖屏，或符合大小要求的横屏来画月亮。',help:['从新月开始。按名称选择任务，或检查后依次探索八个月相。','用鼠标、触摸或触控笔绘画。可选画笔、橡皮擦和笔刷大小；清除后可以重画。','检查后可见参考图与画作相似度的估计值。漏涂和多涂的明亮部分都会计算。','可以多次重试。每次检查后都能前往下个月相，任何分数都不会阻碍前进。']}};
function N294t(k){return N294L[ee.lang||'en'][k]}
function N294tier(){return Ps>=.85?3:Ps>=.6?2:Ps>=.3?1:0}
function N294ring(kind){return `<div class="n294-meter ${kind==='result'?'result':'mission'}"><svg viewBox="0 0 140 140" aria-hidden="true"><circle class="meter-track" cx="70" cy="70" r="58"/><circle class="meter-fill" cx="70" cy="70" r="58" pathLength="100" stroke-dasharray="100" stroke-dashoffset="${kind==='result'?100:100-(vn+1)/8*100}"/></svg><div>${kind==='result'?`<strong id="n294percent" aria-label="${N294t('accuracy')} ${Math.round(Ps*100)}%">${Math.round(Ps*100)}%</strong>`:`<strong>${vn+1}<small>/8</small></strong>`}</div></div>`}
function N294tools(){return `<div class="n294-toolrow" role="group" aria-label="${N294t('tools')}">${N292button('paint','✎ '+N294t('brush'),pf?'active':'')}${N292button('erase','⌫ '+N294t('eraser'),!pf?'active':'')}${N292button('drawclear','↺ '+N294t('clear'))}</div><label class="n294-brushsize"><span>${N294t('size')}</span><input id="n294brush" aria-label="${N294t('size')}" type="range" min="3" max="7" step="1" value="${N294.brush}"><output id="n294brushlabel">${N294t('sizes')[N294.brush<=3?0:N294.brush<=5?1:2]}</output></label>`}
function N294before(){return `<div class="n294-controlhead"><span class="n294-overline">✦ ${N294t('control')}</span><h3>${N292t('phases')[vn]}</h3></div><div class="n294-prehero">${N294ring('mission')}<div class="n294-brief"><b>${N294t('progress')}</b><p>${N294t('instructions')}</p><span aria-hidden="true">✧　✦　✧</span></div></div>${N294tools()}${N292button('drawcheck','✓ '+N294t('check'),'n294-check')}`}
function N294after(){return `<div class="n294-controlhead"><span class="n294-overline">✦ ${N294t('match')}</span><h3>${N294t('accuracy')}</h3></div><div class="n294-resultshero"><div class="n294-scorebox">${N294ring('result')}</div><figure><canvas id="reference" width="300" height="300" aria-label="${N294t('reference')}"></canvas><figcaption>${N294t('reference')}</figcaption></figure></div><p class="n294-encourage">${N294t('feedback')[N294tier()]}</p><small class="n294-approx">${N294t('approx')}</small><div class="n294-resultactions">${N292button('drawretry','↺ '+N294t('retry'))}${N292button('n292next',(vn===7?N292t('finish'):N292t('nextMoon'))+' →','n294-next')}</div>`}
function N292draw(){const checked=Ps!==null;return `<section class="n292-shell n294-shell">${N292nav()}<div class="n294-missionhead"><b>✦ ${N292t('mission')} — ${vn+1}/8</b><span>${N292.checked.filter(Boolean).length}/8 ${N294t('complete')}</span></div><nav class="n294-missions" aria-label="${N292t('mission')}">${N292t('phases').map((name,i)=>`<button data-act="n292phase${i}" aria-pressed="${i===vn}" class="mission-${i} ${i===vn?'selected':''}" style="--tab:${i}"><i aria-hidden="true">${i+1}</i><span>${name}</span><em aria-hidden="true">✦</em></button>`).join('')}</nav><div class="n294-board"><section class="n294-art"><div class="n294-phasebanner"><small>${N294t('your')}</small><h2>${N292t('phases')[vn]}</h2></div><div class="n294-canvasbox"><div class="draw-pad n292-pad n294-pad"><canvas id="drawing" width="400" height="400" tabindex="0" aria-label="${N292t('drawing')} ${N292t('phases')[vn]}"></canvas><div id="n293pen" class="n293-pen ${pf?'':'eraser'}" hidden aria-hidden="true">${N293pencil()}<i class="n293-tip"></i></div><div class="n293-dust" aria-hidden="true">${Array.from({length:6},()=>'<i>✦</i>').join('')}</div><span class="n292-spark s1">✧</span><span class="n292-spark s2">✦</span></div></div></section><aside class="n294-control ${checked?'checked tier-'+N294tier():''}" aria-live="polite">${checked?N294after():N294before()}</aside></div></section>`}
function N294bindPanel(){const slider=we('#n294brush');if(slider)slider.oninput=()=>{N294.brush=ki(+slider.value,3,7);we('#n294brushlabel').textContent=N294t('sizes')[N294.brush<=3?0:N294.brush<=5?1:2]};if(Ps!==null)N294animate()}
function N294animate(){N294stopMeter();const target=Math.round(Ps*100),node=we('#n294percent'),arc=we('.n294-meter.result .meter-fill');if(!node||!arc)return;const animate=N293motion()&&N294.shown!==N294.serial;N294.shown=N294.serial;const start=performance.now();const step=now=>{if(de!=='draw'||Ps===null||!node.isConnected){N294stopMeter();return}const progress=animate?Math.min(1,(now-start)/800):1,eased=1-(1-progress)**3,value=Math.round(target*eased);node.textContent=value+'%';arc.setAttribute('stroke-dashoffset',100-target*eased);if(progress<1)N294.meterRAF=requestAnimationFrame(step);else N294.meterRAF=null};step(start)}
function N294stopMeter(){if(N294.meterRAF!==null)cancelAnimationFrame(N294.meterRAF);N294.meterRAF=null}
function N293invalidate(){if(Ps===null)return;Ps=null;ar=false;N294stopMeter();const panel=we('.n294-control');panel.className='n294-control';panel.innerHTML=N294before();N294bindPanel()}
function N294orientation(){let box=we('#n294mobileEntry');if(!box){box=document.createElement('div');box.id='n294mobileEntry';we('#orientation').append(box)}box.innerHTML=`<p>${N294t('entryNote')}</p>${N292button('n294mobile','✎ '+N294t('entry'),'n294-mobilelaunch')}`;if(de==='draw')we('#orientationText').textContent=N294t('small')}
function N294bind(){N294orientation();if(de==='draw'){N294bindPanel()}else N294stopMeter()}
function N294help(){return `<h2>✎ ${Q('help')} · ${N292t('tabs')[2]}</h2><div class="help-grid">${N294t('help').map((s,i)=>`<div class="help-card"><b>${i+1}</b><p>${s}</p></div>`).join('')}</div>`}

function N294notice(text){const p=we('.n294-brief p');if(p)p.textContent=text}

// Local-only rankings. No network, fabricated records or changes to game scores.
function N295name(value){return typeof value==='string'?value.trim().normalize('NFKC'):''}
function N295identity(value){return N295name(value).toLocaleLowerCase('en')}
function N295validName(value){const name=N295name(value);return !!name&&Array.from(name).length<=20&&!/[\u0000-\u001f\u007f-\u009f]/.test(name)}
function N295category(record){if(record.kind==='quiz')return 'quiz-'+record.mode;if(record.kind==='racer')return ['racer',record.mode,record.slow?'slow':'normal',record.auto?'auto':'manual'].join('-');return ''}
function N295compare(a,b){return b.score-a.score||(a.kind==='quiz'?b.accuracy-a.accuracy:a.timeMs-b.timeMs)||a.achievedAt-b.achievedAt||a.playerId.localeCompare(b.playerId)}
function N295validRecord(r){return !!r&&typeof r==='object'&&N295validName(r.name)&&Number.isSafeInteger(r.score)&&r.score>=0&&Number.isSafeInteger(r.achievedAt)&&r.achievedAt>0&&r.completed===true&&(r.kind==='quiz'?['standard','extended'].includes(r.mode)&&Number.isInteger(r.total)&&r.total===(r.mode==='standard'?8:18)&&r.correct===r.total&&Number.isInteger(r.attempts)&&r.attempts>=r.correct:r.kind==='racer'&&['thrill','training'].includes(r.mode)&&typeof r.slow==='boolean'&&typeof r.auto==='boolean'&&Number.isFinite(r.timeMs)&&r.timeMs>0)}
function N295cleanRecord(r){const c={kind:r.kind,name:N295name(r.name),playerId:N295identity(r.name),score:r.score,achievedAt:r.achievedAt,completed:true,mode:r.mode};if(r.kind==='quiz')Object.assign(c,{correct:r.correct,total:r.total,attempts:r.attempts,accuracy:r.correct/r.attempts});else Object.assign(c,{timeMs:r.timeMs,slow:r.slow,auto:r.auto});c.category=N295category(c);return c}
function N295createStore(storage){const key='moonExplorerGalacticV295';let records=[],lastName='',persistent=true;
 function merge(items){const best=new Map();for(const item of items){if(!N295validRecord(item))continue;const r=N295cleanRecord(item),id=r.category+'\u0000'+r.playerId,old=best.get(id);if(!old||N295compare(r,old)<0)best.set(id,r)}return [...best.values()]}
 try{const text=storage.getItem(key);if(text){const data=JSON.parse(text);if(data&&data.version===1&&Array.isArray(data.records)){records=merge(data.records);if(N295validName(data.lastName))lastName=N295name(data.lastName)}}}catch(e){persistent=false}
 function save(){try{storage.setItem(key,JSON.stringify({version:1,lastName,records}));persistent=true}catch(e){persistent=false}}
 return {get persistent(){return persistent},get lastName(){return lastName},get records(){return records.map(r=>({...r}))},remember(name){if(!N295validName(name))return false;lastName=N295name(name);save();return true},list(category){return records.filter(r=>r.category===category).sort(N295compare).map(r=>({...r}))},record(item){if(!N295validRecord(item))return null;const result=N295cleanRecord(item);records=merge([...records,result]);save();const list=this.list(result.category),index=list.findIndex(r=>r.playerId===result.playerId);return {rank:index+1,best:list[index],improved:list[index].achievedAt===result.achievedAt&&list[index].score===result.score&&N295compare(result,list[index])===0,category:result.category}},clear(){records=[];lastName='';save()}}}
// Monotonic real elapsed gameplay time, independent of capped physics deltas.
function N295makeClock(now=()=>performance.now()){let ms=0,mark=null;return {begin(){ms=0;mark=now()},pause(){if(mark!==null){ms+=Math.max(0,now()-mark);mark=null}},resume(){if(mark===null)mark=now()},value(){return ms+(mark===null?0:Math.max(0,now()-mark))},stop(){this.pause();return ms}}}

