const N295={tab:'quiz',quiz:'standard',difficulty:'thrill',slow:false,auto:true,page:0,pending:null,session:null,clock:N295makeClock(),returnModal:null,draft:null};
function N295t(k){return N295L[ee.lang||'en'][k]}
function N295escape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function N295time(ms){const seconds=Math.floor(Math.max(0,ms)/1000);return String(Math.floor(seconds/60)).padStart(2,'0')+'.'+String(seconds%60).padStart(2,'0')}
function N295date(ms){return new Date(ms).toLocaleDateString(ee.lang==='zh'?'zh-CN':ee.lang==='bm'?'ms-MY':'en-GB',{day:'2-digit',month:'short',year:'numeric'})}
function N295raceCategory(){return ['racer',N295.difficulty,N295.slow?'slow':'normal',N295.auto?'auto':'manual'].join('-')}
function N295currentCategory(){return N295.tab==='quiz'?'quiz-'+N295.quiz:N295raceCategory()}
function N295trophy(){return '<svg class="n295-trophy" viewBox="0 0 80 80" aria-hidden="true"><defs><linearGradient id="cup295" x2="1" y2="1"><stop stop-color="#fff3b9"/><stop offset="1" stop-color="#eeae50"/></linearGradient></defs><path d="M23 16H9v10q0 18 23 18m25-28h14v10q0 18-23 18" fill="none" stroke="#ffd778" stroke-width="6"/><path d="M22 10h36v19q0 20-18 24-18-4-18-24Z" fill="url(#cup295)"/><path d="M40 52v15m-14 4h28" stroke="#ffe2a0" stroke-width="7" stroke-linecap="round"/><path d="m40 19 3 7 8 1-6 5 1 8-6-4-6 4 1-8-6-5 8-1Z" fill="#fffce8"/></svg>'}
function N295medal(rank){return `<svg class="n295-medal" viewBox="0 0 30 36" aria-hidden="true"><path d="m6 1 9 2 9-2-3 17H9Z" fill="${rank===1?'#edb376':rank===2?'#98bbe5':'#cc92b1'}"/><path d="m11 2 4 1 4-1-2 15h-4Z" fill="#eff9ff" opacity=".65"/><circle cx="15" cy="23" r="12" fill="currentColor"/><circle cx="15" cy="23" r="9" fill="none" stroke="#fff" stroke-opacity=".65"/><path d="m15 16 2 4.5 5 .5-3.7 3.4 1 5-4.3-2.6-4.3 2.6 1-5L8 21l5-.5Z" fill="#fff9e9"/></svg>`}
